        draggable: _Bool | None = None,
        edgeColor: _Str | None = None,
        edgeCurved: _Bool | None = None,
        edgeOpacity: _Num | None = None,
        edgeWidth: _Num | None = None,
        glowColor: _Str | None = None,
        glowEnabled: _Bool | None = None,
        glowRadius: _Num | None = None,
        groupColors: _Obj | None = None,
        interactive: _Bool | None = None,
